import ThemeSelector from './Theme';
import BrandLab from './BrandLab';
import Brand from './Brand';
import { TeamMatchup } from './TeamIdentity';
import ManualOddsControls from './ManualOddsControls';
import BenchmarkControls from './BenchmarkControls';
import ResultReviewControls from './ResultReviewControls';
import VisualDashboard from './VisualDashboard';
import DataConnections from './DataConnections';
import SubmissionComparison from './SubmissionComparison';
import { ScoringPolicyNote } from './ScoringReference';
